def check_sum_of_squares(target, num_variables):
    # Check if target can be written as sum of num_variables integer squares
    if target < 0:
        return False

    # We only need to check squares up to target
    max_b = int(target**0.5)
    squares = [i*i for i in range(max_b + 1)]

    def find_combination(remaining_target, k, used_squares):
        if k == 1:
            return remaining_target in used_squares

        for s in used_squares:
            if s <= remaining_target:
                new_target = remaining_target - s
                if find_combination(new_target, k - 1, used_squares):
                    return True
        return False

    # Simpler iteration for small k (k=2 or k=3 required here)
    if num_variables == 2:
        for i in range(max_b + 1):
            j = int((target - i*i)**0.5)
            if j*j == target - i*i:
                return True
        return False

    if num_variables == 3:
        for i in range(max_b + 1):
            for j in range(i, max_b + 1):
                k_sq = target - i*i - j*j
                if k_sq >= 0:
                    k = int(k_sq**0.5)
                    if k*k == k_sq:
                        return True
        return False

    # General search is hard, but we only need k=3 for n=3 test
    return find_combination(target, num_variables, squares)

print(f"Can 7 be written as a sum of 2 integer squares? {check_sum_of_squares(7, 2)}")
print(f"Can 7 be written as a sum of 3 integer squares? {check_sum_of_squares(7, 3)}")
